import Foundation

enum HomeAssistantText: Int, CaseIterable {
    case home, description, tokenHint, url, token, connect, forget, search, visibleEntities, empty, setup
    case connecting, connected, offline, invalidURL, credentials, network, rejected, timeout, keychain, unsupported
    case dashboard, on, off, run, brightness, position, open, close, stop, mode, temperature, low, high, up, down
    case heat, cool, heatCool, auto, dry, fanOnly, unknown, unavailable
    case entitiesPerRow, customName, details, compactOn, compactOff, compactRun
    case extraInfo, firstSensor, secondSensor, none, liveHint
    case rename, originalName
    case connectionSettings, addEntities, entitiesHint
    case pages, createPage, page, pageTitle, deletePage, previousPage, nextPage, pagesHint
    case moveEntity, duplicateEntity, entityOptions
    case defaultColumns, customColumns, fillLastRow, fillLastRowHint
    case selectColor, hue, saturation, applyColor, cancelColor, colorHint
}

struct HomeAssistantStrings {
    let values: [String]
    private init(_ text: String) { values = text.components(separatedBy: "|") }
    subscript(_ key: HomeAssistantText) -> String { values[key.rawValue] }
    func state(_ state: String) -> String {
        switch state {
        case "on": return self[.on]
        case "off": return self[.off]
        case "heat": return self[.heat]
        case "cool": return self[.cool]
        case "heat_cool": return self[.heatCool]
        case "auto": return self[.auto]
        case "dry": return self[.dry]
        case "fan_only": return self[.fanOnly]
        case "unknown": return self[.unknown]
        case "unavailable": return self[.unavailable]
        default: return state
        }
    }
    func error(_ failure: HomeAssistantFailure) -> String {
        switch failure {
        case .invalidURL: return self[.invalidURL]
        case .credentials: return self[.credentials]
        case .network, .protocolError: return self[.network]
        case .rejected: return self[.rejected]
        case .timeout: return self[.timeout]
        case .keychain: return self[.keychain]
        case .unsupported: return self[.unsupported]
        }
    }
    func status(_ connection: HomeAssistantConnection) -> String {
        switch connection {
        case .unconfigured: return self[.setup]
        case .connecting: return self[.connecting]
        case .connected: return self[.connected]
        case .offline: return self[.offline]
        }
    }
    static func localized(_ language: AppLanguage) -> Self {
